-- Perennial schema v1. See docs/schema.md.

-- ---------------------------------------------------------------------------
-- Better Auth (generated by `bunx auth generate --config auth.cli.ts`; keep its
-- column names so library upgrades stay simple). `account` has one row per
-- sign-in method, which is how social login fits in later.
-- ---------------------------------------------------------------------------
create table "user" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null, "isAnonymous" boolean);
create table "session" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" uuid not null references "user" ("id") on delete cascade);
create table "account" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "accountId" text not null, "providerId" text not null, "userId" uuid not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);
create table "verification" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);
create table "rateLimit" ("id" uuid default pg_catalog.gen_random_uuid() not null primary key, "key" text not null unique, "count" integer not null, "lastRequest" bigint not null);
create index "session_userId_idx" on "session" ("userId");
create index "account_userId_idx" on "account" ("userId");
create index "verification_identifier_idx" on "verification" ("identifier");
create index "user_anonymous_idx" on "user" ("createdAt") where "isAnonymous";

-- ---------------------------------------------------------------------------
-- Learner data: synced to the learner's devices (Electric shapes, filtered by
-- user_id). Writes go through /api/write.
-- ---------------------------------------------------------------------------
create table course (
  user_id uuid not null references "user" on delete cascade,
  lang text not null check (lang in ('es', 'de')),
  minutes smallint not null default 7 check (minutes between 1 and 120),
  retention real not null default 0.9 check (retention between 0.7 and 0.99),
  created_at timestamptz not null default now(),
  primary key (user_id, lang)
);

create table review (
  id uuid primary key,                       -- made on the client
  user_id uuid not null references "user" on delete cascade,
  lang text not null,
  word_id text not null,                     -- deck id, user_word id, or form:<lang>:<form>
  skill text not null check (skill in ('read', 'listen', 'write')),
  grade smallint not null check (grade between 1 and 4),
  kind text not null default 'review' check (kind in ('review', 'known')),
  reviewed_at timestamptz not null,
  duration_ms integer not null check (duration_ms >= 0),
  sentence_id text,
  received_at timestamptz not null default now()
);
create index review_user_word on review (user_id, word_id);

create table word_state (
  user_id uuid not null references "user" on delete cascade,
  word_id text not null,
  status text not null check (status in ('queued', 'paused', 'ignored')),
  queued_at timestamptz,
  updated_at timestamptz not null,
  primary key (user_id, word_id)
);

create table user_word (
  id uuid primary key,
  user_id uuid not null references "user" on delete cascade,
  lang text not null,
  lemma text not null,
  gloss text not null,
  pos text,
  forms jsonb not null default '[]',
  notes text,
  deck_id text,
  created_at timestamptz not null default now()
);
create index user_word_user on user_word (user_id);

create table user_sentence (
  id uuid primary key,
  user_id uuid not null references "user" on delete cascade,
  word_id text not null,
  text text not null,
  translation text not null,
  cloze text not null,
  origin text not null check (origin in ('own-text', 'ai')),
  model text,
  created_at timestamptz not null default now()
);
create index user_sentence_user_word on user_sentence (user_id, word_id);

-- Electric needs full rows for updates and deletes it streams.
alter table course replica identity full;
alter table review replica identity full;
alter table word_state replica identity full;
alter table user_word replica identity full;
alter table user_sentence replica identity full;

-- ---------------------------------------------------------------------------
-- Server only.
-- ---------------------------------------------------------------------------
create table ai_usage (
  user_id uuid not null references "user" on delete cascade,
  period text not null,                      -- '2026-10'
  used integer not null default 0,
  primary key (user_id, period)
);

create table ai_spend (
  period text primary key,
  usd numeric(12, 6) not null default 0
);

create table ai_request (
  id bigint generated always as identity primary key,
  user_id uuid references "user" on delete cascade,
  task text not null,
  model text not null,
  prompt_version text not null,
  input_tokens integer,
  output_tokens integer,
  usd numeric(12, 6),
  ms integer,
  ok boolean not null,
  created_at timestamptz not null default now()
);
create index ai_request_created on ai_request (created_at);
